lib:
fn md5hex(text) { return md5(text) }
// 播放地址归一：ting13 系统一换 ysxs 有效证书，并强制 https。
// 原先这段在 probe 与 audio 里各写一遍、audio 里还嵌了三次，改一处要同步四处。
fn fixSrc(u) { return replaceText(replaceText(default(u, ''), '.ting13.top', '.ysxs.top'), 'http://', 'https://') }
fn aesecb(text, key) {
let out = encrypt('AES/ECB/PKCS7Padding', bytes(text), bytes(key))
return typeOf(out) == 'list' ? out : base64Bytes(out)
}
fn aesecbN(text, key) {
return bytesBase64(aesecb(text, key))
}
fn tsEnc(bid, cid, kt, ts) {
let sign = aesecbN(tojson('2.6.5-' + str(ts) + '-' + md5hex(bid + '-' + cid + '.mp3')), '0123456789abcdef')
return aesecbN(tojson({bookID: bid, chapterID: cid, time: ts, koten: kt, sign: sign}), 'nXfMck1YKeuH5ZES')
}
fn tsEncF(bid, cid, kt) {
let sign = aesecbN(tojson('2.6.5-' + md5hex(bid + '-' + cid + '.mp3')), '0123456789abcdef')
return aesecbN(tojson({bookID: bid, chapterID: cid, time: formatDate(now(), 'yyyy-MM-dd'), koten: kt, sign: sign}), 'nXfMck1YKeuH5ZES')
}

// 网页兜底播放地址：两个 fetch 分支共用同一表达式，原先写了两份一样的。
fn wplayUrl(wbook, chTitle) {
  return 'https://m.itingshu.net/play/' + get(matchAll(wbook, 'href="/play/(\\d+_\\d+_\\d+)\\.html"', 1), indexOf(matchAll(wbook, 'href="/play/\\d+_\\d+_\\d+\\.html"[^>]*>[^<]*?([1-9]\\d*)', 1), match(chTitle, '([1-9]\\d*)', 1))) + '.html'
}
// 从网页播放页提取音频地址：优先 var now、其次 <audio src>、最后正则兜底。
fn pickAudio(wp) {
  if (str(wp) == '') { return '' }
  let a = match(wp, 'var\\s+now\\s*=\\s*["\']([^"\']+)', 1)
  if (str(a) != '') { return a }
  let b = match(wp, '<audio[^>]+src="([^"]+)"', 1)
  if (str(b) != '') { return b }
  return default(match(wp, '(https?:\\/\\/[^"\'\\s]+\\.(?:mp3|m4a|m3u8|aac)[^"\'\\s]*)', 1), '')
}
